from topics import T,C,V,table,process,network

T('reliability-foundations',6,'Надёжность информационной системы. Основания расчёта',
'Какие события и интервалы нужно зафиксировать до вычисления показателя?',
'За смену оператор отметил три ошибки, но две были повторными сообщениями об одном отказе. Надёжность нельзя посчитать, пока не определены объект, критерий отказа и правила регистрации.',[
C('Надёжность, отказ и восстановление','Надёжность характеризует сохранение способности выполнять требуемые функции в установленных условиях. Отказ — событие нарушения работоспособности. Восстановление возвращает объект в состояние, допускающее эти функции.',
'Начинаем с функции и допустимых пределов. Если требование — записывать накладную за две секунды, отказом может быть как отсутствие записи, так и устойчивое превышение принятого предела. Ошибка пользователя или предупредительная запись журнала сама по себе ещё не является отказом объекта. Восстановление завершается проверкой функции, а не только запуском процесса. Одинаковые правила нужны для всех наблюдений, иначе показатели будут сравнивать разные события.',
'Отказ — событие нарушения работоспособного состояния объекта по установленному критерию.'),
C('Наработка и календарное время','Наработка — продолжительность или объём работы объекта. Календарный период может включать работу, восстановление, обслуживание и исключённые интервалы. Их границы задают до расчёта.',
'Для сервера наработка часто измеряется часами, для операции — числом выполнений, для устройства — циклами. Нельзя делить число отказов на календарные 24 часа, если объект использовался восемь часов и показатель относится к работе. Одновременно показатель доступности услуги за сутки может специально учитывать ночные часы, если услуга должна работать непрерывно. Единого правильного знаменателя без определения показателя не существует.',
'Наработка — продолжительность или объём выполненной объектом работы.'),
C('Журнал состояний','Учебный период 08:00–16:00: работа 08:00–10:00; восстановление 10:00–10:30; работа 10:30–13:00; обслуживание 13:00–13:30; работа 13:30–16:00.',
'Сумма интервалов составляет восемь часов. Рабочая наработка: 2 + 2,5 + 2,5 = 7 часов; восстановление 0,5 и обслуживание 0,5 дают итог 8. Такая явная проверка не позволяет потерять паузу в знаменателе. Зарегистрирован один отказ в 10:00; обслуживание в 13:00 не является ещё одним отказом по условиям примера.',visual=table(['Состояние','Интервал','Длительность'],[['Работа','08:00–10:00','2 ч'],['Восстановление','10:00–10:30','0,5 ч'],['Работа','10:30–13:00','2,5 ч'],['Обслуживание','13:00–13:30','0,5 ч'],['Работа','13:30–16:00','2,5 ч']],'Учебный журнал. Работа 7 ч; восстановление 0,5 ч; обслуживание 0,5 ч; всего 8 ч.')),
C('Что считается отдельным отказом','Повторные сообщения одного непрерывного нарушения объединяют в один эпизод. Новое нарушение после подтверждённого восстановления может стать новым отказом. Правило зависит от объекта и критерия.',
'Например, десять сообщений «база недоступна» за одну непрерывную остановку не дают десяти отказов. Но если доступ восстановили, подтвердили операцией, а через час отказ повторился, появляются два эпизода. Необходимо хранить начало, окончание, объект и свидетельство восстановления. Время ожидания запчасти может входить в принятый показатель восстановления или выделяться отдельно; соглашение надо назвать.'),
C('Основания и предел вывода','Для расчёта нужны граница объекта, функция, критерий отказа, условия работы, период, наработка, число эпизодов, длительности и выбранная модель. Малый объём наблюдений ограничивает вывод.',
'Один рабочий день без отказа не доказывает нулевую интенсивность и бесконечную надёжность. Из выборки получают оценку, к которой при необходимости добавляют неопределённость. Условия сравниваемых периодов должны быть сопоставимы: рост нагрузки или смена критерия способны изменить число зарегистрированных отказов без изменения оборудования. В этой дисциплине расчётные примеры используют заданные данные; измерительный отчёт обязан сохранять их происхождение.')],
dict(prompt='За одну остановку получено 20 одинаковых сообщений. Восстановления между ними не было. Сколько эпизодов отказа по принятому правилу?',options=['20','1','0','Нельзя считать сообщения, но автоматически берём 10'],correct=1,explanation='По условию один непрерывный эпизод и нет промежуточного восстановления. Сообщение журнала не равно отдельному отказу.'),
dict(task='Подсчитайте отдельные эпизоды отказа. Каждое подтверждённое восстановление завершает эпизод.',output='Введите целое число.',variants=[
V('Повторные сообщения','В 10:00 и 10:05 сообщения о недоступности; в 10:30 подтверждено восстановление. Других нарушений нет.',[('10:00','Начало эпизода 1'),('10:05','Продолжение эпизода 1'),('10:30','Эпизод 1 завершён')],'1','До 10:30 состояние не восстановлено, поэтому оба сообщения описывают один эпизод.',['1']),
V('Новый эпизод','В 10:00 отказ; в 10:30 восстановление подтверждено; в 11:00 новая недоступность; в 11:10 восстановлено.',[('10:00–10:30','Эпизод 1'),('10:30','Функция подтверждена'),('11:00–11:10','Эпизод 2')],'2','После завершённого восстановления возникло новое нарушение: два отдельных эпизода.',['2'])]),'reliability')

T('single-metrics',6,'Единичные показатели надёжности',
'Что именно оценивают вероятность безотказной работы, наработка на отказ и время восстановления?',
'Две системы могут одинаково часто отказывать, но восстанавливаться за разное время. Одно число не описывает оба свойства.',[
C('Вероятность безотказной работы','R(t) — вероятность выполнить требуемую работу без отказа на заданном интервале t в установленных условиях. Для N однотипных объектов с полным наблюдением до t оценка R̂(t) = Nбез_отказа(t) / N.',
'Важны одинаковый горизонт и отсутствие потерянных наблюдений. Если из 100 объектов 92 проработали весь интервал без отказа, оценка равна 0,92. Нельзя считать оставшимися без отказа устройства, которые перестали наблюдать раньше срока. Для цензурированных наблюдений нужны другие методы, выходящие за этот вводный расчёт. R(100 ч) и R(1000 ч) отвечают на разные вопросы.',
'R(t) = P{отказ не наступил до t}; t указывается с единицей времени.'),
C('Наработка на отказ и восстановление','Для заданной выборки восстанавливаемых объектов: оценка наработки на отказ T̄ = суммарная наработка / число отказов. Среднее восстановление T̄в = сумма завершённых длительностей восстановления / их число.',
'Суммарная наработка может включать несколько одинаковых объектов, поэтому пять серверов по 100 часов дают 500 серверо-часов. В числитель не попадает простой, если определена именно рабочая наработка. Для восстановления нужны сопоставимые границы: от зарегистрированного начала нарушения до подтверждения функции. Среднее не показывает худший случай, поэтому полезно сохранять исходные длительности. При нуле отказов простое отношение не даёт конечную оценку T̄.',
'T̄ = Σtработы / nотказов; T̄в = Σtвосстановления / nвосстановлений.'),
C('Экспоненциальная модель','При принятой постоянной интенсивности отказов λ: R(t) = exp(−λt). Для этой модели среднее время до отказа невосстанавливаемого объекта равно 1/λ; для стационарной модели повторных отказов отдельно оговаривают соответствующие предпосылки.',
'Это модель, а не универсальный закон. Постоянство λ плохо описывает выраженный износ или ранние дефекты. В показателе экспоненты произведение λt безразмерно: при λ в 1/ч время берут в часах. Из оценки по наблюдениям нельзя незаметно получить точный параметр природы. В расчётной задаче мы явно принимаем модель и затем интерпретируем результат на указанном горизонте.',
'При λ = const: R(t) = e^(−λt), λ в 1/ч, t в ч.'),
C('Разбор: три разных результата','Учебные данные: суммарная наработка 1200 ч, 6 отказов; восстановления 1, 2, 1, 3, 2, 3 ч. T̄ = 200 ч; T̄в = 12/6 = 2 ч. При принятой λ = 1/200 ч⁻¹: R(20 ч) ≈ 0,9048.',
'Сначала считаем наблюдаемые средние: 1200/6=200 и 12/6=2. Затем делаем отдельный модельный шаг: принимаем постоянную интенсивность 0,005 в час. На горизонте 20 часов λt=0,1; exp(−0,1)=0,904837. Значение 0,9048 не означает доступность в течение 90,48 процента календаря: это вероятность пройти 20 часов без отказа в принятой модели. Быстрое восстановление не входит в эту формулу.',visual=table(['Показатель','Расчёт','Результат'],[['Наработка на отказ','1200 / 6','200 ч'],['Восстановление','12 / 6','2 ч'],['Интенсивность модели','1 / 200','0,005 ч⁻¹'],['R(20 ч)','exp(−0,005 × 20)','0,9048']],'Наблюдаемые оценки и модельная вероятность различаются по смыслу.')),
C('Порядок проверки расчёта','Назовите объект и период, выпишите единицы, отделите работу от простоя, проверьте число завершённых эпизодов, выберите формулу и укажите округление. Нулевая выборка и ноль отказов требуют отдельного комментария.',
'Проверка размерности выявляет многие ошибки: деление часов на отказы даёт часы на отказ, а деление отказов на часы — оценку частоты. Перед экспонентой переводим единицы. Если среднее восстановление посчитано по пяти завершённым случаям, нельзя молча добавить шестой незавершённый как ноль. В отчёте сохраняют исходные данные, чтобы результат можно было пересчитать.')],
dict(prompt='Какое утверждение о R(20 ч)=0,9048 корректно в принятой модели?',options=['Система доступна 90,48% любого календарного года','Вероятность пройти 20 ч без отказа равна примерно 0,9048','Среднее восстановление 0,9048 ч','Отказ обязательно произойдёт через 20 ч'],correct=1,explanation='R(t) относится к безотказному прохождению горизонта t. Восстановление и календарная готовность — другие показатели.'),
dict(task='Рассчитайте оценку наработки на отказ: суммарная наработка делится на число отказов.',output='Введите ответ в часах без единицы.',variants=[
V('Обычный период','Суммарная наработка 1800 ч; 6 отказов.',[('Числитель','1800 ч работы'),('Знаменатель','6 отказов'),('Деление','1800 / 6 = 300 ч')],'300','Получаем 300 ч на отказ для данной выборки. Время восстановления не вычитают ещё раз: числитель уже задан как наработка.',['300']),
V('Больше отказов','Та же суммарная наработка 1800 ч; 9 отказов.',[('Числитель','1800 ч работы'),('Знаменатель','9 отказов'),('Деление','1800 / 9 = 200 ч')],'200','При той же наработке большее число отказов снижает оценку до 200 ч. Это сравнение требует одинакового критерия отказа.',['200'])]),'reliability')

T('availability',6,'Комплексные показатели надёжности',
'Почему готовность и техническое использование дают разные числа?',
'В журнале есть аварийное восстановление и плановое обслуживание. Включение обслуживания в знаменатель меняет вопрос, на который отвечает показатель.',[
C('Коэффициент готовности','Коэффициент готовности — вероятность быть работоспособным в заданный момент. В простой стационарной двухсостоянийной модели работы и восстановления Kг = T̄ / (T̄ + T̄в). Плановые периоды, когда применение по назначению не предусмотрено, этим выражением не описываются.',
'В отличие от R(t), здесь учитывается возврат к работе. Если объект часто отказывает, но быстро восстанавливается, стационарная готовность может быть высокой, хотя пройти длинный интервал без отказа маловероятно. Для расчёта по конечному журналу можно определить наблюдаемую долю рабочего времени в явно выбранном фонде «работа плюс восстановление». Это эмпирическое отношение не следует выдавать за доказанный стационарный параметр.',
'В принятой модели: Kг = T̄ / (T̄ + T̄в).'),
C('Коэффициент технического использования','В учебном учёте Kти = Tработы / (Tработы + Tвосстановления + Tобслуживания), когда эти интервалы не перекрываются и охватывают принятый фонд времени. Исключённые периоды описывают отдельно.',
'Техническое использование оценивает долю времени, реально занятого работой, с учётом простоев на восстановление и обслуживание. Перед вычислением нужно решить, учитываем ли ожидание, выключение вне смены и профилактику. При иной границе наблюдения появится иной показатель. Перекрывающиеся интервалы не складывают дважды: если обслуживание проведено внутри аварийного простоя, нужна принятая классификация времени.',
'Kти = Tработы / (Tработы + Tвосстановления + Tобслуживания) для неперекрывающихся интервалов учебного фонда.'),
C('Разбор: один журнал, два знаменателя','Учебный фонд: работа 900 ч, восстановление 20 ч, плановое обслуживание 80 ч. Наблюдаемая доля работы без планового обслуживания = 900/920 ≈ 0,9783; Kти = 900/1000 = 0,9.',
'Сумма 900+20+80 даёт 1000 часов. Первое отношение исключает из фонда обслуживание и отвечает более узкому вопросу; второе показывает использование всего заданного фонда. Разница не является арифметическим противоречием. Если это договорный показатель доступности услуги, его правила надо взять из договора: называть 97,83 процента исполнением любого SLA нельзя.',visual=table(['Интервал','Часы','В каком знаменателе'],[['Работа','900','В обоих'],['Восстановление','20','В обоих'],['Обслуживание','80','Только в полном учебном фонде'],['Итоги','920 и 1000','Разные вопросы']],'0,9783 и 0,9 получены из одного журнала при разных границах учёта.')),
C('Как изменить показатель','При T̄=200 ч и T̄в=2 ч Kг≈0,9901. Сокращение восстановления до 1 ч даёт Kг≈0,9950 без изменения частоты отказов. Удвоение наработки до 400 ч при T̄в=2 ч даёт то же отношение.',
'Одинаковый коэффициент может скрывать разные режимы: редкие долгие остановки и частые короткие. Поэтому решение об улучшении выбирают по последствиям для функции. Для непрерывной технологической операции даже короткий перерыв может быть недопустим. Для справочного сервиса быстрое восстановление может оказаться достаточным. Коэффициент не заменяет ограничения на максимальную остановку.'),
C('Порядок расчёта','Составьте неперекрывающиеся интервалы, проверьте их сумму, выберите фонд времени, вычислите отношение и подпишите его смысл. В проценты переводят умножением на 100; разность процентов и процентных пунктов различают.',
'Если доля выросла с 0,90 до 0,95, прирост составляет 5 процентных пунктов, а относительный рост доли — около 5,56 процента. Для краткого отчёта достаточно указать исходное и новое значения с одинаковой точностью. Самая существенная проверка перед сравнением — одинаковая граница фонда; иначе улучшение может быть следствием исключения неудобных интервалов.')],
dict(prompt='Работа 900 ч, восстановление 20 ч, обслуживание 80 ч. Какое выражение соответствует Kти в заданном полном фонде?',options=['900 / 920','900 / 1000','20 / 900','80 / 1000'],correct=1,explanation='Полный неперекрывающийся фонд составляет 900+20+80=1000 ч; доля работы равна 0,9.'),
dict(task='Рассчитайте Kти по указанному полному фонду. Ответ округлите до двух знаков после запятой.',output='Введите долю от 0 до 1, например 0,80.',variants=[
V('С обслуживанием','Работа 760 ч, восстановление 20 ч, обслуживание 20 ч.',[('Полный фонд','760 + 20 + 20 = 800 ч'),('Отношение','760 / 800'),('Округление','0,95')],'0,95','В знаменателе оба вида простоя. Kти=0,95; выражение 760/780 исключило бы обслуживание.',['0,95','0.95']),
V('Дополнительное обслуживание','Работа 720 ч, восстановление 20 ч, обслуживание 60 ч.',[('Полный фонд','720 + 20 + 60 = 800 ч'),('Отношение','720 / 800'),('Округление','0,90')],'0,90','При том же фонде увеличение обслуживания уменьшило рабочее время; Kти=0,90. Сравнение с Kг требует другого знаменателя.',['0,90','0.90','0,9','0.9'])]),'reliability')

T('system-reliability',6,'Надёжность системы из нескольких элементов. Резервирование',
'Как логика выполнения функции определяет формулу надёжности?',
'Два сетевых кабеля могут образовать резерв, а могут оказаться зависимыми от одного устройства. Сначала зададим условие успеха, затем посчитаем вероятность.',[
C('Логическое последовательное соединение','Если для функции нужны все независимые элементы, Rс(t)=∏Ri(t). Это соединение в модели надёжности; физическая геометрия кабелей сама по себе его не определяет.',
'Для доступа к записи нужны рабочее место, сеть и сервис. Отказ любого обязательного звена прерывает эту функцию, поэтому модель последовательная даже при физической звезде сети. Все Ri относятся к одному горизонту t и одинаково сформулированному успеху. Независимость означает отсутствие учтённой общей причины, меняющей вероятность совместного события; её нельзя предполагать только потому, что корпуса разные.',
'При независимых отказах и необходимости всех элементов: Rс(t) = R1(t) × … × Rn(t).'),
C('Параллельное резервирование','Если достаточно хотя бы одного из независимых работоспособных каналов, Rп(t)=1−∏(1−Ri(t)). В простой модели переключение идеально, каждый оставшийся канал выполняет требуемую функцию.',
'Удобнее посчитать противоположное событие: оба канала отказали. Для двух каналов с вероятностью успеха 0,9 вероятность каждого отказа 0,1, совместного — 0,01, успеха хотя бы одного — 0,99. Если один канал не выдерживает полную нагрузку или переключение может не сработать, это другая модель. Резервная копия данных не является автоматически параллельным работающим каналом.',
'При независимости и идеальном резерве: Rп(t) = 1 − (1−R1(t)) × … × (1−Rn(t)).'),
C('Разбор: сеть и обязательный сервер','Учебные данные одного горизонта: сервер R=0,98; каждый из двух независимых сетевых каналов R=0,95. Без резерва R=0,98×0,95=0,931. С идеальным резервом сети R=0,98×[1−0,05²]=0,97755.',
'Сначала считаем подсистему сети: 1−0,0025=0,9975. Затем включаем обязательный сервер последовательно: 0,98×0,9975=0,97755. Резервирование сети не делает обязательный сервер резервированным. Улучшение составляет 0,04655, или 4,655 процентного пункта. Это модельный результат на заданном горизонте, а не обещание годовой доступности.',visual=table(['Конфигурация','Сеть','Вся функция с сервером'],[['Один канал','0,95','0,98 × 0,95 = 0,931'],['Два независимых','1 − 0,05² = 0,9975','0,98 × 0,9975 = 0,97755'],['Обязательный сервер','0,98','Остаётся общим ограничением']],'Все вероятности заданы на одном горизонте; переключение и пропускная способность считаются достаточными.')),
C('Общая причина отказа','Два канала через один коммутатор зависят от него. При Rкомм=0,97 и независимой от него резервной группе с R=0,99 общая вероятность =0,97×0,99=0,9603, а не 0,99.',
'Отдельно вынесем обязательный общий компонент. Если он недоступен, оба пути недоступны одновременно; считать их полностью независимыми нельзя. Аналогичные зависимости создают питание, охлаждение, общий операторский кабель и ошибочная общая конфигурация. В модели нужно либо показать общий элемент, либо использовать другой способ учёта зависимости; подставлять произведение без объяснения опасно.'),
C('Порядок расчёта и контроль','Определите функцию и горизонт; нарисуйте условие успеха; выделите общие элементы; проверьте независимость и переключение; рассчитайте группы от внутренних к общим. Результат должен находиться от 0 до 1.',
'Для обязательного последовательного включения результат не может превышать надёжность слабейшего обязательного элемента. Для идеальной независимой параллельной группы он не меньше надёжности каждого канала. Эти проверки ловят перестановку формул. После выбора решения нужна эксплуатационная проверка переключения и восстановления основной конфигурации: расчёт не проверяет фактическую настройку.')],
dict(prompt='Два обязательных независимых элемента имеют R=0,9 и R=0,8 на одном горизонте. Какова надёжность функции?',options=['0,98','0,85','0,72','1,7'],correct=2,explanation='Необходимы оба элемента: последовательная логика, 0,9×0,8=0,72. 0,98 относится к идеальной параллельной группе.'),
dict(task='Рассчитайте R системы и округлите до четырёх знаков. Каналы независимы; переключение идеально; каждый выдерживает нагрузку.',output='Введите долю от 0 до 1.',variants=[
V('Резерв без общей причины','Два параллельных канала R1=R2=0,90. Общих обязательных элементов в условии нет.',[('Отказ одного','1 − 0,90 = 0,10'),('Оба отказали','0,10 × 0,10 = 0,01'),('Успех','1 − 0,01 = 0,9900')],'0,9900','Достаточно любого канала. Вычитаем вероятность совместного отказа из единицы: 0,99.',['0,9900','0.9900','0,99','0.99']),
V('Общий коммутатор','Та же пара каналов по 0,90; обязателен общий коммутатор с R=0,97, независимый от группы.',[('Группа каналов','1 − 0,10² = 0,99'),('Общий компонент','0,97 последовательно'),('Успех функции','0,99 × 0,97 = 0,9603')],'0,9603','Общий коммутатор требуется при любом канале. Итог 0,9603; 0,99 без этого множителя завышает результат.',['0,9603','0.9603'])]),'reliability')

T('information-integrity',6,'Достоверность информации в системе',
'Как отличить обнаружение искажения от подтверждения правильности сведений?',
'Контрольная сумма файла совпадает, но в нём записана неверная цена. Проверим, что именно подтверждают разные виды контроля.',[
C('Источники искажения','Ошибки возникают при вводе, передаче, хранении, преобразовании, объединении и использовании устаревших данных. Достоверность связывают с соответствием сведений реальному объекту или принятому эталону.',
'Система может безошибочно хранить ошибочно введённый документ. И наоборот, корректный первичный документ может исказиться при преобразовании единиц. Поэтому проверяют происхождение, момент актуальности и преобразования. В учебном расчёте заранее задаём эталон: проверенная ведомость или контрольный набор. Без него можно обнаруживать противоречия, но нельзя объявлять каждую непротиворечивую запись истинной.',
'Достоверность информации — соответствие сведений описываемому объекту или установленному достоверному основанию в заданном контексте.'),
C('Показатели по проверенной выборке','Для заданной сплошь проверенной выборки q=Nош/N и D=1−q. Nош — число записей с хотя бы одной обнаруженной ошибкой; повторные ошибки внутри одной записи не увеличивают число ошибочных записей.',
'Знаменатель и единица учёта должны совпадать. Если показатель относится к записям, нельзя складывать отдельные неверные поля как число записей. Для показателя по полям используют другой знаменатель. Полученная доля характеризует проверенную выборку и критерий контроля; она не становится автоматически вероятностью правильности всех данных системы. Непроверенные записи не относят к безошибочным.',
'qзап = Nошибочных_записей / Nпроверенных_записей; Dзап = 1 − qзап.'),
C('Контроли отвечают на разные вопросы','Форматный контроль проверяет представление; диапазонный — допустимые значения; ссылочный — наличие связанных объектов; сверка — соответствие независимому основанию; контрольная сумма — изменение байтов в пределах выбранного метода.',
'Контрольная сумма обнаруживает определённые изменения представления, но не понимает цену, адрес или факт получения товара. Диапазон пропустит правдоподобную, но неверную цену. Сверка с независимым источником добавляет смысловое основание, если сам источник актуален и проверен. Для защиты от умышленного изменения выбирают подходящие криптографические механизмы; обычный CRC не доказывает авторство.',visual=table(['Контроль','Что может обнаружить','Чего не подтверждает'],[['Формат','Неверный тип или структуру','Реальность значения'],['Диапазон','Выход за допустимый предел','Правильность внутри диапазона'],['Ссылка','Нет связанного товара','Правильность выбранного товара'],['Сумма / хеш','Изменение представления','Истинность исходных сведений'],['Сверка','Расхождение с основанием','Безошибочность самого основания']],'Несколько контролей дополняют друг друга.')),
C('Разбор: записи и поля','Учебная выборка: 200 записей по 5 полей. В 8 записях найдено 10 неверных полей. По записям q=8/200=0,04, D=0,96. По полям qполей=10/1000=0,01; показатели отвечают на разные вопросы.',
'Число неверных полей больше числа ошибочных записей, потому что отдельная запись содержит несколько ошибок. Для доли записей учитываем каждую запись один раз. Если взять 10/200, смешаются единицы. В отчёте указываем критерий: запись считается ошибочной при хотя бы одном неправильном поле, а все поля были проверены по эталону. Эти сведения позволяют другому специалисту воспроизвести расчёт.'),
C('Исправление и повторный контроль','Фиксируют исходное расхождение, источник, причину и исправление. Затем повторяют соответствующий контроль и проверяют связанные расчёты и обмен. Исправленная запись не должна потерять историю основания.',
'Если неправильная единица уже попала в отчёт закупки, исправления карточки недостаточно: требуется пересчёт зависимых результатов по правилам системы. После восстановления из копии возможна устаревшая версия справочника. Повторная проверка должна охватывать путь возникновения ошибки, а не только итоговое число исправленных записей. При выборочной проверке границы обобщения формулируются отдельно.')],
dict(prompt='Хеш файла совпадает с хешем принятой копии. Какой вывод обоснован?',options=['Все цены истинны','Файл соответствует принятой копии в пределах проверки; смысловая правильность требует отдельного основания','Ошибок ввода никогда не было','Сведения актуальны на сегодняшний момент'],correct=1,explanation='Проверка представления не устанавливает реальность и актуальность сведений. Ошибка могла существовать уже в принятой копии.'),
dict(task='Рассчитайте D по записям. Каждая ошибочная запись учитывается один раз. Ответ — доля.',output='Введите число от 0 до 1.',variants=[
V('Три ошибочные записи','Проверены все 150 записей выборки; 3 содержат ошибки, всего неверных полей 7.',[('Единица','Запись, не поле'),('q','3 / 150 = 0,02'),('D','1 − 0,02 = 0,98')],'0,98','Для доли записей берём 3, а не 7: D=0,98. Вывод относится к этой проверенной выборке.',['0,98','0.98']),
V('Пятнадцать ошибочных записей','Проверены все 150 записей выборки; 15 содержат ошибки, всего неверных полей 18.',[('Единица','Запись, не поле'),('q','15 / 150 = 0,10'),('D','1 − 0,10 = 0,90')],'0,90','D=0,90. Наличие 18 неверных полей не меняет числитель показателя по записям.',['0,90','0.90','0,9','0.9'])]),'integrity')

T('performance',6,'Производительность информационной системы',
'Как измерение связывает время ответа, нагрузку и узкое место?',
'После увеличения числа пользователей среднее время почти не изменилось, но часть запросов ждёт несколько секунд. Одного среднего недостаточно.',[
C('Показатели производительности','Задержка — длительность операции; пропускная способность — число завершённых операций за время. Ошибки и очередь измеряют вместе с ними. Загрузка ресурса помогает искать причину, но не заменяет результат для пользователя.',
'Время ответа измеряют на определённой границе: клиентское полное время и время сервера могут различаться. Пропускная способность относится к завершениям, а не только к отправленным запросам. Если система отклоняет половину нагрузки, короткое время оставшихся запросов нельзя назвать улучшением. Нужно сохранять долю ошибок, профиль операции, объём данных и параллельность.',
'Пропускная способность X = число завершённых операций / интервал наблюдения; единица — операций/с.'),
C('Среднее и процентиль','Учебные десять задержек: 100, 100, 100, 100, 100, 100, 100, 100, 100, 1100 мс. Среднее 200 мс. По правилу ближайшего ранга p95 находится на позиции ceil(0,95×10)=10 и равен 1100 мс.',
'Среднее складывает все длительности и делит на десять: (900+1100)/10=200. Оно скрывает, что один пользователь ждал в одиннадцать раз дольше остальных. Процентиль требует назвать способ вычисления; на малой выборке он груб. В этой учебной задаче используется ближайший ранг, а не интерполяция. Для реального вывода собирают более представительную выборку и сохраняют распределение.',visual=table(['Характеристика','Вычисление','Результат'],[['Сумма','9×100 + 1100','2000 мс'],['Среднее','2000 / 10','200 мс'],['Ранг p95','ceil(0,95×10)','10'],['p95 ближайшего ранга','10-е значение','1100 мс']],'Явное правило процентиля предотвращает расхождение ответов разных инструментов.')),
C('Узкое место и гипотеза','Узкое место ограничивает достижимый результат при заданной нагрузке. Ищут согласованные признаки: рост очереди, насыщение ресурса и увеличение задержки. Высокая загрузка одного ресурса сама по себе ещё не доказывает причину.',
'Если CPU почти свободен, а запросы ждут блокировку базы, добавление ядер может не помочь. Если канал насыщен передачей видео, ускорение диска не устранит очередь в сети. Сначала формулируют гипотезу и выбирают измерение, которое отличит её от альтернативы. Изменяют один существенный фактор и повторяют сопоставимый прогон; иначе нельзя приписать изменение результата конкретной мере.'),
C('Разбор: сравнение двух прогонов','Учебный одинаковый профиль: A — 600 завершений за 60 с, p95=1,8 с, ошибок 0; B — 900 за 60 с, p95=1,2 с, ошибок 0. X выросла с 10 до 15 оп/с; p95 уменьшился на 0,6 с.',
'Сравнение допустимо только при одинаковых операциях, данных и границах измерения. Относительный рост пропускной способности составляет (15−10)/10=50 процентов; снижение p95 — (1,8−1,2)/1,8 примерно 33,3 процента. Это наблюдение для двух прогонов, а не доказательство масштабирования на любую нагрузку. Если B запускался с прогретым кэшем, а A с холодным, это отдельное условие, требующее контроля.'),
C('Порядок измерения','Опишите операцию, данные, окружение и нагрузку; выполните подготовку; соберите завершения, задержки, ошибки и ресурсы; повторите сопоставимый прогон. Зафиксируйте гипотезу, изменение и критерий успеха.',
'Лабораторная использует учебный стенд или подготовленный набор результатов. Нагрузку не направляют на произвольные рабочие сервисы. Прогрев и длительность выбирают по цели, а не по магическому числу повторов. Для малой учебной выборки вывод остаётся ограниченным. Проверка после улучшения должна показать сохранение правильности данных вместе с изменением времени.')],
dict(prompt='Система завершила 1200 операций за 60 с. Какова пропускная способность?',options=['0,05 оп/с','20 оп/с','1200 мс','60 оп/с'],correct=1,explanation='X=1200/60=20 завершённых операций в секунду. Это не задержка отдельной операции.'),
dict(task='Рассчитайте p95 по ближайшему рангу: отсортируйте 10 значений и возьмите ceil(0,95×10)-е.',output='Введите задержку в миллисекундах без единицы.',variants=[
V('Есть длинный хвост','Девять значений по 80 мс и одно 900 мс.',[('Размер','10 наблюдений'),('Ранг','ceil(9,5)=10'),('10-е значение','900 мс')],'900','При ближайшем ранге p95 малой выборки совпал с максимумом 900. Среднее здесь 162 мс и отвечает на другой вопрос.',['900']),
V('Хвост сокращён','Девять значений по 80 мс и одно 300 мс.',[('Размер','10 наблюдений'),('Ранг','ceil(9,5)=10'),('10-е значение','300 мс')],'300','p95=300 мс по принятому правилу. Сравниваем одинаковый профиль и отмечаем ограниченность десяти наблюдений.',['300'])]),'performance')

T('improvement',6,'Повышение надёжности и обоснование выбора меры',
'Как выбрать меру по расчёту и последствиям отказа?',
'Можно купить резервный сервер или ускорить восстановление. Выбор зависит от причины остановок, допустимого перерыва и подтверждаемого эффекта.',[
C('Резервирование, отказоустойчивость и обслуживание','Резервирование добавляет ресурсы для сохранения функции. Отказоустойчивость — способность продолжать требуемую работу при предусмотренных отказах. Регламентное обслуживание поддерживает состояние, но может требовать простоя.',
'Наличие двух серверов ещё не означает отказоустойчивость: нужны переключение, актуальные данные и достаточная мощность оставшегося узла. Резервная копия помогает восстановить данные, но обычно предполагает перерыв и возможную потерю последних изменений в пределах принятого окна. Обслуживание уменьшает часть причин отказа, однако неверно выполненная профилактика сама может создать нарушение.',
'Отказоустойчивость — способность сохранять требуемую функцию при оговорённых отказах компонентов.'),
C('Связь причины и меры','При отказах дисков рассматривают отказоустойчивое хранение и независимые копии; при длительном ремонте — запасные части и инструкцию; при общей потере питания — независимые пути питания в пределах проекта.',
'Меру выбирают для конкретной причины. Второй диск не устраняет потерю питания здания, а UPS не восстанавливает ошибочно удалённую базу. Ускорение восстановления требует проверенного порядка и ресурсов, иначе время в расчёте останется предположением. После вмешательства сохраняют штатную конфигурацию и проверяют способность вернуть резерв в готовность.',visual=table(['Наблюдение','Возможная мера','Чем подтвердить'],[['Долго ищут причину','Мониторинг и диагностическая инструкция','Время локализации на стенде'],['Долго ждут деталь','Совместимый запас и порядок замены','Учебная замена'],['Общая точка отказа','Разделение зависимости','Испытание предусмотренного отказа'],['Потеря данных','Копии и восстановление','Проверка восстановленных операций']],'Связь меры с причиной требуется до оценки стоимости.')),
C('Разбор: эффект времени восстановления','Учебные данные: T̄=100 ч, T̄в=4 ч. Kг=100/104≈0,96154. Проверенная мера сокращает T̄в до 1 ч: Kг=100/101≈0,99010. Частота отказов в этой модели не изменилась.',
'Прирост готовности составляет примерно 0,02856, или 2,856 процентного пункта. Эта мера не увеличила вероятность безотказной работы на длинном интервале: она уменьшила долю времени восстановления. Если требование запрещает любой перерыв, даже новый один час не подходит. Если допускается восстановление до двух часов, новое время проходит критерий при условии, что оно подтверждено применимым испытанием.'),
C('Ограничения модели и стоимость','Сначала исключают варианты, не выполняющие обязательные условия; затем сравнивают эффект, стоимость, сопровождение и новые зависимости. Общая причина и неидеальное переключение могут уменьшить эффект резерва.',
'Например, два сервера с общим накопителем сохраняют зависимость от него. Модель 1−(1−R)² здесь не описывает всю систему. Стоимость включает не только закупку: требуется обновление, проверка копий, обучение и обслуживание резерва. В учебном обосновании достаточно прозрачной таблицы с исходными допущениями; выдуманные рыночные цены не нужны.'),
C('План проверки выбранной меры','Зафиксируйте исходную конфигурацию, допустимое испытание, ожидаемое переключение или восстановление, проверку данных и возврат в штатное состояние. Результат сравните с расчётным критерием.',
'Проверка проводится на разрешённом стенде и предусмотренным способом. Во время отказа отслеживают именно пользовательскую функцию: запись, чтение или выдачу сигнала. После восстановления проверяют отсутствие дублирования и потери подтверждённых операций. Завершение испытания включает готовность резерва к следующему отказу; работа на единственном оставшемся узле не равна восстановлению полной схемы.')],
dict(prompt='T̄ не изменилось, T̄в уменьшилось с 4 до 1 ч. Что изменилось в простой модели?',options=['Только вероятность безотказной работы любого интервала','Коэффициент готовности вырос за счёт сокращения восстановления','Все общие причины отказа исчезли','Надёжность стала точно 1'],correct=1,explanation='В Kг=T̄/(T̄+T̄в) уменьшился знаменатель. Частота отказов и общие зависимости сами по себе не изменились.'),
dict(task='Какая мера проходит обязательный предел восстановления: A или B? Выберите самый дешёвый допустимый вариант; цены условные.',output='Введите A или B.',variants=[
V('Допустимо 2 часа','A: восстановление 3 ч, стоимость 10. B: 1 ч, стоимость 25. Оба значения подтверждены учебной проверкой.',[('Обязательный предел','Не более 2 ч'),('A','3 > 2: исключён'),('B','1 ≤ 2: допустим')],'B','A дешевле, но не выполняет обязательное условие. Из заданных вариантов проходит B.',['b','B']),
V('Допустимо 4 часа','Те же A: 3 ч за 10; B: 1 ч за 25. Теперь допустимо не более 4 ч.',[('Обязательный предел','Не более 4 ч'),('Допустимость','Оба проходят'),('Стоимость','10 < 25')],'A','После изменения ограничения оба допустимы. По заданному критерию минимальной стоимости выбирается A.',['a','A'])]),'reliability')
